mapper.body:
{
  "model": "anthropic/claude-sonnet-4-6",
  "messages": [
    {
      "role": "user",
      "content": "Write a 3-sentence friendly email to {{1.body.payload.invitee.name}} who just canceled a call. Offer to reschedule. Understanding, never pushy. Return only the email body."
    }
  ],
  "temperature": 0.7,
  "max_tokens": 300
}

{
  "from": "{{env.RESEND_FROM_NAME}} <{{env.RESEND_FROM_ADDRESS}}>",
  "to": ["{{1.body.payload.invitee.email}}"],
  "subject": "Let us find a better time",
  "text": "{{3.data.choices[0].message.content}}\n\nWhen you're ready, grab a time that works for you here:\n{{env.CALENDLY_LINK}}"
}

{
  "properties": {
    "hs_timestamp": "{{now}}",
    "hs_note_body": "No-show recovery email sent to {{1.body.payload.invitee.email}} after Calendly cancellation. Subject: Let us find a better time. Sent at {{formatDate(now; \"YYYY-MM-DD HH:mm:ss\"; \"America/New_York\")}} Eastern Time. Calendly event: {{1.body.payload.event_type.name}}. Invitee: {{1.body.payload.invitee.name}}."
  }
}

{
  "from": "{{env.CWI_ALERT_FROM_ADDRESS}}",
  "to": ["{{env.ADMIN_EMAIL}}"],
  "subject": "[ALERT] No-Show Recovery — Error in Scenario L",
  "text": "Scenario L (No-Show Recovery) encountered an error.

Failed Module: {{errorHandler.moduleId}}
Error Type: {{errorHandler.type}}
Error Message: {{errorHandler.message}}
Timestamp: {{formatDate(now; "YYYY-MM-DD HH:mm:ss"; "America/New_York")}} Eastern

Invitee Name: {{1.body.payload.invitee.name}}
Invitee Email: {{1.body.payload.invitee.email}}
Calendly Event: {{1.body.payload.event_type.name}}
Canceled At: {{1.body.payload.invitee.canceled_at}}

Please follow up manually."
}
